#endif
void exercise(const fs::path& root){const auto m=root/"tiny.mtx",f=root/"features.tsv",o=root/"observations.tsv",store=root/"counts.qmx";write(m,tiny);write(f,"feature_id\nG1\nG2\nG3\n");write(o,"observation_id\nA\nB\nC\nD\n");ExpressionMatrixImportOptions options;options.work_bytes=8u*1024*1024;const auto imported=import_expression_matrix(m.u8string(),f.u8string(),o.u8string(),store.u8string(),options);check(imported.file_sha256=="174b4ea68d6022fbab3a488b0a070d0a550853e42e410880707e6f5d8b0b6018","Legacy schema1 import bytes differ from the frozen native tiny fixture");check(imported.metadata.features==3 && imported.metadata.observations==4 && imported.metadata.entries==6 && imported.matrix_bytes==tiny.size() && imported.peak_work_bytes<=options.work_bytes,"Streamed shape, bytes and accounted import work");
    const auto source=open_expression_matrix(store.u8string(),imported.file_sha256);rejects<std::invalid_argument>([&]{source->spatial_page(0,1);});check(source->metadata().source_sha256==imported.metadata.source_sha256 && source->file_sha256()==imported.file_sha256,"Exact physical/logical source association");check(source->feature_index("G3")==2 && source->observation_index("D")==3 && !source->feature_index("Absent"),"Stable indexed catalogue lookup");auto page=source->feature_page(1,2);check(page.size()==2 && page[0].id=="G2" && page[1].index==2 && page[1].sha256.size()==64,"Paged feature IDs/chunk identities");check(source->observation_page(1,2)==std::vector<std::string>{"B","C"},"Paged observation identities");rejects<std::out_of_range>([&]{source->feature_page(3,1);});
    ExpressionMatrixSelection selection;selection.features={2,0};const auto all=source->read(selection);check(all.offsets==std::vector<std::uint64_t>{0,2,4} && all.observation_indices==std::vector<std::uint64_t>{0,3,0,1} && all.counts==std::vector<std::uint64_t>{11,7,5,9007199254740993ULL},"Independent sparse values/order retain precision beyond2^53");
    selection.features={0,1,2};selection.observations=std::vector<std::uint64_t>{1,3};auto subset=source->read(selection);check(subset.offsets==std::vector<std::uint64_t>{0,1,1,2} && subset.observation_indices==std::vector<std::uint64_t>{1,3} && subset.counts==std::vector<std::uint64_t>{9007199254740993ULL,7},"Independent cohort sparse values and implicit zeros");
    selection.features={1};selection.observations=std::vector<std::uint64_t>{0,2};subset=source->read(selection);check(subset.counts==std::vector<std::uint64_t>{UINT64_MAX,0},"Exact uint64 maximum and explicit measured zero");selection.observations=std::vector<std::uint64_t>{};const auto empty=source->read(selection);check(empty.counts.empty() && empty.offsets==std::vector<std::uint64_t>{0,0} && empty.sha256!=subset.sha256,"Empty cohort remains empty with distinct identity");
    selection.observations.reset();const auto worker=std::async(std::launch::async,[&]{return source->read(selection);}).get();check(worker.counts==std::vector<std::uint64_t>{UINT64_MAX,0},"Owned immutable source reads on native worker");rejects<std::invalid_argument>([&]{source->read(selection,1);});selection.features={0,0};rejects<std::invalid_argument>([&]{source->read(selection);});selection.features={3};rejects<std::invalid_argument>([&]{source->read(selection);});selection.features={0};selection.observations=std::vector<std::uint64_t>{2,1};rejects<std::invalid_argument>([&]{source->read(selection);});
    std::atomic<bool> cancelled{true};rejects<WorkflowCancelled>([&]{source->feature_page(0,1,64u*1024*1024,&cancelled);});rejects<WorkflowCancelled>([&]{import_expression_matrix(m.u8string(),f.u8string(),o.u8string(),(root/"cancelled.qmx").u8string(),options,&cancelled);});check(!fs::exists(root/"cancelled.qmx"),"Cancelled import leaves no published store");
    const auto store_bytes=bytes(store);rejects<WorkflowOutputExists>([&]{import_expression_matrix(m.u8string(),f.u8string(),o.u8string(),store.u8string(),options);});check(bytes(store)==store_bytes,"Existing store never overwritten");rejects<WorkflowInputChanged>([&]{open_expression_matrix(store.u8string(),std::string(64,'a'));});
    fs::rename(m,root/"matrix-offline.mtx");fs::rename(f,root/"features-offline.tsv");fs::rename(o,root/"observations-offline.tsv");auto reopened=open_expression_matrix(store.u8string(),imported.file_sha256);selection={};selection.features={2,0};check(reopened->read(selection).sha256==all.sha256,"Reopen/query does not need or rescan original text inputs");const auto relocated=root/"relocated.qmx";fs::copy_file(store,relocated);auto relinked=open_expression_matrix(relocated.u8string(),imported.file_sha256);check(relinked->metadata().source_sha256==source->metadata().source_sha256 && relinked->read(selection).sha256==all.sha256,"Verified byte-identical relocation retains source/block identity");
    for(const auto& bad:{std::string("%%MatrixMarket matrix coordinate real general\n3 4 0\n"),std::string("%%MatrixMarket matrix coordinate integer general\n3 4 2\n1 1 5\n1 1 6\n"),std::string("%%MatrixMarket matrix coordinate integer general\n3 4 1\n4 1 5\n"),std::string("%%MatrixMarket matrix coordinate integer general\n3 4 1\n1 1 -1\n"),std::string("%%MatrixMarket matrix coordinate integer general\n3 4 1\n1 1 18446744073709551616\n"),std::string("%%MatrixMarket matrix coordinate integer general\n3 4 1\n"),std::string("%%MatrixMarket matrix coordinate integer general\n3 4 0\n1 1 2\n"),std::string("%%MatrixMarket matrix coordinate integer general\n3 4 1\n")+std::string(4097,'1')+"\n"}){write(m,bad);rejects([&]{import_expression_matrix(m.u8string(),(root/"features-offline.tsv").u8string(),(root/"observations-offline.tsv").u8string(),(root/"bad.qmx").u8string(),options);});check(!fs::exists(root/"bad.qmx"),"Invalid import never publishes partial metadata");no_stage(root);}
    write(m,tiny);write(f,"feature_id\nG1\nG1\nG3\n");write(o,"observation_id\nA\nB\nC\nD\n");rejects<std::invalid_argument>([&]{import_expression_matrix(m.u8string(),f.u8string(),o.u8string(),(root/"duplicate.qmx").u8string(),options);});write(f,"feature_id\nG1\nG2\nG3\n");auto tiny_budget=options;tiny_budget.store_bytes=4096;rejects([&]{import_expression_matrix(m.u8string(),f.u8string(),o.u8string(),(root/"limited.qmx").u8string(),tiny_budget);});check(!fs::exists(root/"limited.qmx"),"Store byte budget refuses incomplete output");
    write(f,"id-1\tRepeated symbol\tGene Expression\nid-2\tRepeated symbol\tGene Expression\nid-3\tOther\tGene Expression\n");write(o,"A\nB\nC\nD\n");auto tenx=options;tenx.format=ExpressionCatalogueFormat::Tenx;const auto labels=import_expression_matrix(m.u8string(),f.u8string(),o.u8string(),(root/"tenx.qmx").u8string(),tenx);auto named=open_expression_matrix(labels.path,labels.file_sha256);page=named->feature_page(0,3);check(page[0].id=="id-1" && page[1].id=="id-2" && page[0].name==page[1].name && named->feature_index("id-3")==2,"Stable source IDs permit repeated display symbols");
#ifdef QPX_MATRIX_SQLITE
    fs::copy_file(store,root/"incomplete.qmx");sql(root/"incomplete.qmx","UPDATE metadata SET value='0' WHERE key='complete'");rejects<std::invalid_argument>([&]{open_expression_matrix((root/"incomplete.qmx").u8string());});fs::copy_file(store,root/"corrupt.qmx");sql(root/"corrupt.qmx","UPDATE counts SET value=x'0900000000000000' WHERE feature=0 AND observation=0");auto corrupt=open_expression_matrix((root/"corrupt.qmx").u8string());check(corrupt->metadata().source_sha256!=source->metadata().source_sha256,"Changed sidecar bytes cannot alias source identity");selection.features={0};selection.observations=std::vector<std::uint64_t>{0};rejects<std::invalid_argument>([&]{corrupt->read(selection);});
#endif
    write(fs::path(store.u8string()+"-wal"),"unreviewed writer");rejects<WorkflowInputChanged>([&]{source->read(selection);});fs::remove(fs::path(store.u8string()+"-wal"));{std::ofstream changed(store,std::ios::binary|std::ios::app);changed.put('x');}rejects<WorkflowInputChanged>([&]{source->require_current();});no_stage(root);
}
void interruptions(const fs::path& root,bool change){const auto dir=root/(change?"source-change":"mid-cancel");fs::create_directory(dir);const auto matrix=dir/"matrix.mtx",features=dir/"features.tsv",observations=dir/"observations.tsv",store=dir/"store.qmx";{std::ofstream out(matrix);out<<"%%MatrixMarket matrix coordinate integer general\n1000 1000 100000\n";for(unsigned i=0;i<100000;++i)out<<i%1000+1<<' '<<i/1000+1<<" 1\n";}std::ostringstream f,o;f<<"feature_id\n";o<<"observation_id\n";for(int i=0;i<1000;++i){f<<'G'<<i<<'\n';o<<'O'<<i<<'\n';}write(features,f.str());write(observations,o.str());std::atomic<bool> cancelled{false},done{false},fired{false},blocked{false};std::promise<void> watching;auto watching_ready=watching.get_future();auto watcher=std::async(std::launch::async,[&]{watching.set_value();while(!done.load()){std::error_code error;for(fs::directory_iterator it(dir,error),end;!error && it!=end;it.increment(error)){if(it->path().filename().u8string().rfind(".qpx-expression-",0)!=0)continue;if(change){
#ifdef _WIN32
    const auto handle=CreateFileW(matrix.c_str(),FILE_APPEND_DATA,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);
    if(handle==INVALID_HANDLE_VALUE){check(GetLastError()==ERROR_SHARING_VIOLATION,"Only the active read-sharing guard may block the mutation");blocked.store(true);}else{const char newline='\n';DWORD written=0;const bool ok=WriteFile(handle,&newline,1,&written,nullptr)!=0;CloseHandle(handle);check(ok && written==1,"Watcher changed synthetic input");}
#else
    std::ofstream out(matrix,std::ios::binary|std::ios::app);out.put('\n');out.close();check(bool(out),"Watcher changed synthetic input");
#endif
    }else cancelled.store(true);fired.store(true);return;}std::this_thread::sleep_for(std::chrono::milliseconds(1));}});
    watching_ready.wait();const auto before=bytes(matrix);bool refused=false;std::optional<ExpressionMatrixImportResult> completed;try{ExpressionMatrixImportOptions options;options.work_bytes=8u*1024*1024;completed=import_expression_matrix(matrix.u8string(),features.u8string(),observations.u8string(),store.u8string(),options,&cancelled);}catch(const WorkflowCancelled&){if(!change)refused=true;else{done.store(true);watcher.wait();throw;}}catch(const WorkflowInputChanged&){if(change)refused=true;else{done.store(true);watcher.wait();throw;}}catch(...){done.store(true);watcher.wait();throw;}done.store(true);watcher.get();check(fired.load(),"Interruption observer must actually exercise its boundary");if(blocked.load()){check(change && completed && !refused && bytes(matrix)==before,"Read sharing keeps the captured input unchanged");auto stable=open_expression_matrix(completed->path,completed->file_sha256);check(stable->metadata().entries==100000 && stable->read(ExpressionMatrixSelection{{0},{}}).counts.size()==100,"Blocked mutation permits only a complete stable snapshot");}else check(refused && !fs::exists(store),"Cancelled/changed input must not advertise a complete store");no_stage(dir);
}
void real(const fs::path& root,const fs::path& raw){ExpressionMatrixImportOptions options;options.format=ExpressionCatalogueFormat::Tenx;const auto result=import_expression_matrix((raw/"matrix.mtx").u8string(),(raw/"features.tsv").u8string(),(raw/"barcodes.tsv").u8string(),(root/"mouse-brain.qmx").u8string(),options);check(result.metadata.features==32285 && result.metadata.observations==2702 && result.metadata.entries==16031101 && result.matrix_bytes==197229475,"Admitted full real matrix dimensions/bytes");auto source=open_expression_matrix(result.path,result.file_sha256);const auto projected=raw.parent_path()/"mouse-brain";SpatialCountsOptions selected;selected.features=read_spatial_feature_catalogue((projected/"features.tsv").u8string()).features;const auto prior=read_spatial_counts((projected/"counts.mtx").u8string(),(projected/"features.tsv").u8string(),(projected/"positions.tsv").u8string(),selected);
    const auto ids=source->observation_page(0,2702);check(ids.size()==prior.observations.size(),"Real observation axis length");for(std::size_t i=0;i<ids.size();++i)check(ids[i]==prior.observations[i].id,"Real barcode order/identity equals prior independent projection");ExpressionMatrixSelection q;for(const auto& label:selected.features){const auto split=label.find('|');check(split!=std::string::npos,"Prior feature ID carries source identifier");auto index=source->feature_index(label.substr(split+1));check(bool(index),"Full store contains prior marker ID");q.features.push_back(*index);}const auto block=source->read(q);std::size_t nonzero=0;for(std::size_t f=0;f<q.features.size();++f){auto at=block.offsets[f];for(std::size_t i=0;i<ids.size();++i){std::uint64_t value=0;if(at<block.offsets[f+1] && block.observation_indices[at]==i)value=block.counts[at++];check(value==prior.counts[i*q.features.size()+f],"Every real selected count equals independent retained projection");nonzero+=value!=0;}check(at==block.offsets[f+1],"All sparse entries accounted");}check(nonzero==14550,"Retained marker nonzero count unchanged");q.features={0};const auto unprojected=source->feature_page(0,1).at(0);check(std::find(selected.features.begin(),selected.features.end(),unprojected.name+"|"+unprojected.id)==selected.features.end(),"Real query is outside old six-gene projection");const auto unseen=source->read(q);check(!unseen.counts.empty() && open_expression_matrix(result.path,result.file_sha256)->read(q).sha256==unseen.sha256,"Unprojected real gene query/reopen exact identity");
    std::ofstream report(root/"real.json");report<<"{\"features\":"<<result.metadata.features<<",\"observations\":"<<result.metadata.observations<<",\"entries\":"<<result.metadata.entries<<",\"matrix_bytes\":"<<result.matrix_bytes<<",\"store_bytes\":"<<result.file_bytes<<",\"peak_work_bytes\":"<<result.peak_work_bytes<<",\"import_ms\":"<<result.elapsed_ms<<",\"source_sha256\":\""<<result.metadata.source_sha256<<"\",\"file_sha256\":\""<<result.file_sha256<<"\",\"unprojected_id\":\""<<unprojected.id<<"\",\"unprojected_block_sha256\":\""<<unseen.sha256<<"\",\"selected_counts_equal\":true}\n";report.close();check(bool(report),"Write real native matrix evidence");std::cout<<"Full matrix imported natively: "<<result.file_bytes<<" store bytes / "<<result.elapsed_ms<<"ms / peak accounted "<<result.peak_work_bytes<<" bytes; every retained selected count equals and an unprojected gene reopens exactly\n";
}
int main(int argc,char** argv){try{if(!has_expression_matrix_storage()){rejects<std::runtime_error>([]{open_expression_matrix("disabled.qmx");});std::cout<<"Disabled native expression storage refuses explicitly\n";return 0;}const auto root=argc>1?fs::u8path(argv[1]):fs::current_path()/("expression-matrix-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(root);exercise(root);interruptions(root,false);interruptions(root,true);if(argc==4 && std::string(argv[2])=="--real")real(root,fs::u8path(argv[3]));std::cout<<"Native indexed expression: exact uint64, sparse/cohort/catalogue reads, identity/reopen/relink, malformed/corrupt/stale/cancel and atomic interruption checks pass\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
